// Location handling in JavaScript
const nameParts = name.split('|');
const displayName = nameParts[0].trim();
const location = nameParts.length > 1 ? nameParts[1].trim() : '';

// Location display in HTML
<div class="location-info">
  <div class="name">{{displayName}}</div>
  <div class="location" v-if="location">
    <span class="location-icon">📍</span>
    {{location}}
  </div>
</div>

/* Location styling in CSS */
.location-info {
  display: flex;
  flex-direction: column;
  gap: 0.25em;
}

.location {
  display: flex;
  align-items: center;
  gap: 0.5em;
  font-size: 0.9em;
  color: var(--location-color, #666);
}

.location-icon {
  font-size: 1.1em;
}

/* Disco Ball Background Effects */

/* Style 1: Full Background Disco Effect */
.style-1 .disco-background {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: radial-gradient(circle at center, 
    rgba(255, 255, 255, 0.1) 0%,
    rgba(255, 255, 255, 0.05) 20%,
    transparent 60%);
  animation: discoRotate 20s linear infinite;
  pointer-events: none;
}

/* Style 2: Disco Ball Accent Effect */
.style-2 .disco-accent {
  position: absolute;
  right: 10px;
  top: 50%;
  transform: translateY(-50%);
  width: 40px;
  height: 40px;
  background: radial-gradient(circle at center,
    rgba(255, 255, 255, 0.8) 0%,
    rgba(255, 255, 255, 0.4) 50%,
    transparent 100%);
  animation: discoPulse 3s ease-in-out infinite;
  border-radius: 50%;
}

@keyframes discoRotate {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

@keyframes discoPulse {
  0% { transform: translateY(-50%) scale(1); opacity: 0.8; }
  50% { transform: translateY(-50%) scale(1.2); opacity: 1; }
  100% { transform: translateY(-50%) scale(1); opacity: 0.8; }
}

// Disco effect initialization
function initDiscoEffect(style) {
  const container = document.querySelector('.lower-third-container');

  if (style === 1) {
    // Style 1: Full background disco effect
    const discoBg = document.createElement('div');
    discoBg.className = 'disco-background';
    container.appendChild(discoBg);
  } else if (style === 2) {
    // Style 2: Disco ball accent
    const discoAccent = document.createElement('div');
    discoAccent.className = 'disco-accent';
    container.appendChild(discoAccent);
  }
}

// Update disco effect based on style changes
function updateDiscoEffect(newStyle) {
  const container = document.querySelector('.lower-third-container');
  const existingDisco = container.querySelector('.disco-background, .disco-accent');

  if (existingDisco) {
    existingDisco.remove();
  }

  initDiscoEffect(newStyle);
}
